def priority(task, state, guard=0.5, big=1e9, spt=1.0, beta=0.5):
    slack = task.due - state.now - task.estimated_runtime
    mean_est = max(state.mean_est, 1e-6)
    congestion = state.queue_work / max(state.capacity * mean_est, 1e-6)
    threshold = -guard * mean_est / max(1.0 + beta * congestion, 1e-6)
    if slack >= threshold:
        return big - slack
    else:
        return -spt * task.estimated_runtime * max(task.resource_need, 1e-6)

