def priority(task, state, k=1.0, m=2.0, b=0.5, alpha=0.5, bonus=1000.0, beta=0.5):
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    need = max(task.resource_need, 1e-6)
    deficit = max(0.0, need - state.free)
    wait_cores = beta * deficit * mean_est / max(state.capacity, 1e-6)
    slack = task.due - state.now - est - wait_cores
    tier = m if task.tenant == 'premium' else 1.0
    wait = max(0.0, state.now - task.release)
    denom = max(est * (need ** alpha), 1e-6)
    if slack >= 0.0:
        return bonus + tier * task.weight / denom * math.exp(-slack / (max(k, 1e-6) * mean_est)) * (1.0 + b * wait / est)
    else:
        return -bonus + tier / denom  # tuned (k=0.958,m=1.21,b=0.433,alpha=0.156,bonus=1e+03,beta=0.18)

