def priority(task, state, A=1.0, C=0.1, B=1e6):
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now - est
    wait_ratio = (state.now - task.release) / est
    base = -est + A * wait_ratio - C * max(slack, 0.0)
    return base - (B if slack < 0 else 0.0)  # tuned (A=2.57,C=0.242,B=1.59e+06)

