def priority(task, state, k=1.0, m=2.0, c=1.0, a=0.5, r=0.5, b=0.5, d=0.5, w=0.0,
             align=1.0, variant=1.0, sv=1.0):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    slack = task.due - state.now - est
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'alignment':
        tm = align
    elif task.task_type == 'variant_calling':
        tm = variant
    else:
        tm = sv
    weight = max(task.weight, 1e-6) ** w
    wait = max(0.0, state.now - task.release)
    aging = 1.0 + b * wait / est
    if slack < 0.0:
        return - (est ** a) * (cores ** r)
    load = state.queue_work / max(state.capacity, 1e-6)
    if load < c:
        return tier * tm * weight * aging / ((est ** a) * (cores ** r))
    due_in = max(task.due - state.now, 1e-6)
    return tier * tm * weight * aging / ((due_in ** d) * (est ** a) * (cores ** r))

def priority(task, state, f_align=1.0, f_var=1.0, f_sv=1.0, late_penalty=0.0, spt_weight=0.0):
    if task.task_type == 'alignment':
        factor = f_align
    elif task.task_type == 'variant_calling':
        factor = f_var
    else:
        factor = f_sv
    est = max(factor * task.estimated_runtime, 1e-6)
    slack = task.due - state.now - est
    base = -slack + spt_weight / est
    if slack < 0:
        base -= late_penalty
    return base  # tuned (f_align=0.302,f_var=3.73,f_sv=0.38,late_penalty=0,spt_weight=0)

