def priority(task, state, k=1.0, m=2.0, a=1.0, a_urgent=0.5, f=0.2, p_bonus=1.5, w_align=1.0, w_variant=1.0, w_sv=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    slack = task.due - state.now - est
    if task.tenant == 'premium':
        tier = m if slack < mean else p_bonus
    else:
        tier = 1.0
    if task.task_type == 'alignment':
        type_mult = w_align
    elif task.task_type == 'variant_calling':
        type_mult = w_variant
    else:
        type_mult = w_sv
    if slack < 0.0:
        return tier * type_mult * task.weight * f / (est ** a_urgent)
    else:
        alpha = a_urgent if slack < mean else a
        return tier * type_mult * task.weight / (est ** alpha) * math.exp(-slack / (k * mean))

def priority(task, state, s=20.0, a=5.0, m=1.5):
    slack = task.due - state.now - task.estimated_runtime
    base = -max(task.due, state.now + task.estimated_runtime)
    risk = max(0.0, s - slack) if slack > 0.0 else 0.0
    tier = m if task.tenant == 'premium' else 1.0
    return base + a * tier * risk  # tuned (s=12.5,a=6.58,m=0.643)
